/**
 * One row of an SbMenu: the word, an optional 24 dp icon, and what it does. [checked] not null = a check row of a
 * single choice (spec/02 §4.18 `menuitemradio`): a 16 dp slot at the start with the check in accent when true, empty
 * when false (the words align); TalkBack reads a radio button. [toggled] not null = an on/off row (`menuitemcheckbox`,
 * §14.8) with the same slot; TalkBack reads a checkbox. [group] = the head of the group this row belongs to; a head
 * stands before the first row of each group (§14.8).
 */
@Immutable
data class SbMenuItem(
    val label: String,
    val onClick: () -> Unit,
    val icon: ImageVector? = null,
    val enabled: Boolean = true,
    val checked: Boolean? = null,
    val toggled: Boolean? = null,
    val group: String? = null,
)

/**
 * Overflow menu (spec/02 §4.10): overlay layer without shadow (D46), rows of 48 dp. [danger] = the one destructive
 * row, always last after a hairline, in danger, without the 45° cut; its onClick opens SbConfirmDialog (D39). The
 * layer opens in a Popup that keeps the gutter from the window's sides (§14.8) with M3's scale-and-fade; with
 * sbReduceMotion() it only fades.
 */
@Composable
fun SbMenu(
    expanded: Boolean,
    onDismissRequest: () -> Unit,
    items: List<SbMenuItem>,
    modifier: Modifier = Modifier,
    danger: SbMenuItem? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val overlay = t.elevation.overlay
    val rows: @Composable ColumnScope.() -> Unit = {
        val starts = items.indices.filter { it == 0 || items[it].group != items[it - 1].group }
        starts.forEachIndexed { groupIndex, start ->
            val end = starts.getOrNull(groupIndex + 1) ?: items.size
            val head = items[start].group
            Column(Modifier.semantics {
                isTraversalGroup = true
                if (head != null) contentDescription = head
            }) {
                if (head != null) SbMenuHead(head, first = start == 0)
                for (index in start until end) SbMenuRow(items[index], c.text, c.textMuted, onDismissRequest)
            }
        }
        if (danger != null) {
            if (items.isNotEmpty()) {
                Box(
                    Modifier
                        .fillMaxWidth()
                        .padding(vertical = t.space.s1)
                        .height(t.borderWidth.hairline)
                        .background(c.border),
                )
            }
            SbMenuRow(danger, c.danger, c.danger, onDismissRequest)
        }
    }
    val reduce = sbReduceMotion()
    val shown = remember { MutableTransitionState(false) }
    shown.targetState = expanded
    if (!shown.currentState && !shown.targetState) return
    val margin = with(LocalDensity.current) { t.size.targetTouch.roundToPx() }
    val side = with(LocalDensity.current) { t.spacing.gutter.roundToPx() }
    var origin by remember { mutableStateOf(TransformOrigin(0f, 0f)) }
    Popup(
        popupPositionProvider = remember(margin, side) {
            SbMenuPosition(margin, side) { anchor, menu -> origin = sbMenuOrigin(anchor, menu) }
        },
        onDismissRequest = onDismissRequest,
        properties = PopupProperties(focusable = true),
    ) {
        AnimatedVisibility(
            visibleState = shown,
            // M3's own entry (§14.8: the same values as its DropdownMenu, which keeps no gutter): fade in 30 ms and
            // scale from 0.8 in 120 ms out of the anchor; with reduced motion only sbEnter()'s fade
            enter = if (reduce) sbEnter() else fadeIn(tween(30)),
            exit = fadeOut(tween(if (reduce) t.motion.durationShort else 75, easing = t.motion.easingStandard)),
        ) {
            val scale by transition.animateFloat(
                transitionSpec = { tween(120, easing = LinearOutSlowInEasing) },
                label = "SbMenuScale",
            ) { if (!reduce && it == EnterExitState.PreEnter) 0.8f else 1f }
            Surface(
                modifier = Modifier.graphicsLayer {
                    scaleX = scale
                    scaleY = scale
                    transformOrigin = origin
                },
                shape = t.shapes.container,
                color = overlay.surface,
                tonalElevation = 0.dp,
                shadowElevation = overlay.shadowElevation,
                border = BorderStroke(overlay.borderWidth, overlay.borderColor),
            ) {
                Column(
                    modifier
                        .widthIn(min = 200.dp, max = 320.dp)
                        .padding(vertical = t.space.s2)
                        .width(IntrinsicSize.Max)
                        .verticalScroll(rememberScrollState()),
                    content = rows,
                )
            }
        }
    }
}

/**
 * Where SbMenu stands: under its anchor at the start edge (the end edge when the start does not fit), above the
 * anchor when there is no room below, never closer than [margin] to the window's top or bottom and never closer than
 * [side] (the gutter, §14.8) to its sides while the window has room for that. [placed] gets anchor and menu bounds.
 */
private class SbMenuPosition(
    private val margin: Int,
    private val side: Int = 0,
    private val placed: (IntRect, IntRect) -> Unit = { _, _ -> },
) : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val w = popupContentSize.width
        val h = popupContentSize.height
        val ltr = layoutDirection == LayoutDirection.Ltr
        val start = if (ltr) anchorBounds.left else anchorBounds.right - w
        val end = if (ltr) anchorBounds.right - w else anchorBounds.left
        val inset = if (windowSize.width - w >= 2 * side) side else 0
        val x = (if (start >= inset && start + w <= windowSize.width - inset) start else end)
            .coerceIn(inset, (windowSize.width - w - inset).coerceAtLeast(inset))
        val y = when {
            anchorBounds.bottom + h <= windowSize.height - margin -> anchorBounds.bottom
            anchorBounds.top - h >= margin -> anchorBounds.top - h
            else -> (windowSize.height - margin - h).coerceAtLeast(0)
        }
        placed(anchorBounds, IntRect(x, y, x + w, y + h))
        return IntOffset(x, y)
    }
}

/** The point the menu grows from: where it meets its anchor (M3's own rule for its DropdownMenu). */
private fun sbMenuOrigin(anchor: IntRect, menu: IntRect): TransformOrigin {
    val x = when {
        menu.left >= anchor.right -> 0f
        menu.right <= anchor.left -> 1f
        menu.width == 0 -> 0f
        else -> ((maxOf(anchor.left, menu.left) + minOf(anchor.right, menu.right)) / 2 - menu.left).toFloat() / menu.width
    }
    val y = when {
        menu.top >= anchor.bottom -> 0f
        menu.bottom <= anchor.top -> 1f
        menu.height == 0 -> 0f
        else -> ((maxOf(anchor.top, menu.top) + minOf(anchor.bottom, menu.bottom)) / 2 - menu.top).toFloat() / menu.height
    }
    return TransformOrigin(x, y)
}

/** The ⋮ button of a top bar with its SbMenu; [contentDescription] = „Menü öffnen“ from the table. */
@Composable
fun SbOverflowMenu(
    items: List<SbMenuItem>,
    modifier: Modifier = Modifier,
    danger: SbMenuItem? = null,
    contentDescription: String = sbMessages().openMenu,
) {
    var expanded by remember { mutableStateOf(false) }
    SbOverflowMenu(items, expanded, { expanded = it }, modifier, danger, contentDescription)
}

/** [SbOverflowMenu] whose open state the app holds (§14.8): a command or another button may open it. */
@Composable
fun SbOverflowMenu(
    items: List<SbMenuItem>,
    expanded: Boolean,
    onExpandedChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier,
    danger: SbMenuItem? = null,
    contentDescription: String = sbMessages().openMenu,
) {
    Box(modifier) {
        SbIconButton(SebaroIcons.Outline.MoreVertical, contentDescription, onClick = { onExpandedChange(true) })
        SbMenu(expanded = expanded, onDismissRequest = { onExpandedChange(false) }, items = items, danger = danger)
    }
}

/** A group head inside SbMenu (§14.8): label textMuted, 32 dp, a heading, a hairline above unless [first]. */
@Composable
private fun SbMenuHead(word: String, first: Boolean) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    if (!first) {
        Box(
            Modifier
                .fillMaxWidth()
                .padding(vertical = t.space.s1)
                .height(t.borderWidth.hairline)
                .background(c.border),
        )
    }
    Box(
        Modifier
            .fillMaxWidth()
            .heightIn(min = t.space.s8)
            .padding(horizontal = t.space.s4)
            .semantics { heading() },
        contentAlignment = Alignment.CenterStart,
    ) {
        SbWrapText(word, SebaroTheme.typography.label.copy(fontWeight = SebaroTheme.typography.body.fontWeight), c.textMuted)
    }
}

/**
 * One 48 dp menu row: icon in [iconInk], word in [ink]; disabled = textMuted; a check row (item.checked) has the 16 dp
 * check slot first. Closes the menu, then runs.
 */
@Composable
private fun SbMenuRow(item: SbMenuItem, ink: Color, iconInk: Color, close: () -> Unit) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val fill = when {
        !item.enabled -> Color.Transparent
        pressed -> c.pressedFill
        hovered -> c.hoverFill
        else -> Color.Transparent
    }
    val checked = item.checked ?: item.toggled
    val run = {
        close()
        item.onClick()
    }
    Row(
        Modifier
            .fillMaxWidth()
            .heightIn(min = t.size.targetTouch)
            .background(fill)
            .sbFocusRingInset(interaction)
            .then(
                if (checked == null) {
                    Modifier.clickable(
                        interactionSource = interaction,
                        indication = null,
                        enabled = item.enabled,
                        role = Role.Button,
                        onClick = run,
                    )
                } else if (item.toggled != null) {
                    Modifier.toggleable(
                        value = checked,
                        interactionSource = interaction,
                        indication = null,
                        enabled = item.enabled,
                        role = Role.Checkbox,
                        onValueChange = { run() },
                    )
                } else {
                    Modifier.selectable(
                        selected = checked,
                        interactionSource = interaction,
                        indication = null,
                        enabled = item.enabled,
                        role = Role.RadioButton,
                        onClick = run,
                    )
                },
            )
            .padding(horizontal = t.space.s4),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        if (checked != null) {
            Box(Modifier.size(t.size.iconSm), contentAlignment = Alignment.Center) {
                if (checked) {
                    Icon(
                        SebaroIcons.Outline16.Check,
                        contentDescription = null,
                        tint = if (item.enabled) c.accent else c.textMuted,
                        modifier = Modifier.size(t.size.iconSm),
                    )
                }
            }
        }
        val icon = item.icon
        if (icon != null) {
            Icon(icon, contentDescription = null, tint = if (item.enabled) iconInk else c.textMuted, modifier = Modifier.size(t.size.iconLg))
        }
        Text(item.label, style = SebaroTheme.typography.body, color = if (item.enabled) ink else c.textMuted)
    }
}
